// Native stages ATLAS / PACK / TRACE plus the internal SOLVE stage used by
// the JSON driver (main.py) for the joint cache-budgeted image planning.
#include "engine.hpp"
#include <cstdlib>
#include <iostream>

namespace {

std::string to_hex(const std::vector<uint8_t>& img) {
    static const char* d = "0123456789abcdef";
    std::string s;
    s.reserve(img.size() * 2);
    for (uint8_t c : img) { s.push_back(d[c >> 4]); s.push_back(d[c & 15]); }
    return s;
}

std::vector<uint8_t> from_hex(const std::string& s) {
    if (s.size() % 2) throw std::runtime_error("image hex length");
    std::vector<uint8_t> out(s.size() / 2);
    auto nib = [](char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    for (size_t i = 0; i < out.size(); ++i) {
        int a = nib(s[2 * i]), b = nib(s[2 * i + 1]);
        if (a < 0 || b < 0) throw std::runtime_error("image hex digit");
        out[i] = (uint8_t)((a << 4) | b);
    }
    return out;
}

void print_answer(const Answer& a) {
    std::cout << a.hop << ' ' << a.run << ' ' << a.path.size();
    for (uint32_t off : a.path) std::cout << ' ' << off;
    std::cout << '\n';
}

int run_atlas() {
    size_t n;
    std::cin >> n;
    std::vector<Route> routes;
    routes.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        std::string s;
        int length, hop;
        std::cin >> s >> length >> hop;
        if (!std::cin) throw std::runtime_error("truncated native input");
        routes.push_back({parse_key(s), length, hop});
    }
    std::vector<Run> runs = compile_runs(routes);
    std::cout << runs.size() << '\n';
    for (const Run& r : runs)
        std::cout << hexkey(r.start) << ' ' << r.hop << '\n';
    return 0;
}

int run_pack() {
    size_t r, n, a;
    std::cin >> r >> n >> a;
    std::vector<U128> starts;
    std::vector<int> hops;
    for (size_t i = 0; i < r; ++i) {
        std::string s;
        int hop;
        std::cin >> s >> hop;
        if (!std::cin) throw std::runtime_error("truncated native input");
        starts.push_back(parse_key(s));
        hops.push_back(hop);
    }
    std::vector<LayoutNode> nodes(n);
    for (size_t i = 0; i < n; ++i) {
        LayoutNode& nd = nodes[i];
        size_t b;
        std::cin >> nd.lo >> nd.span >> nd.mode >> nd.cached >> b;
        if (!std::cin) throw std::runtime_error("truncated native input");
        for (size_t j = 0; j < b; ++j) {
            int c;
            std::cin >> c;
            nd.kind = 0;
            nd.kids.push_back(c);
        }
        if (b == 0) nd.kind = 1;
    }
    std::vector<U128> addresses;
    for (size_t i = 0; i < a; ++i) {
        std::string s;
        std::cin >> s;
        if (!std::cin) throw std::runtime_error("truncated native input");
        addresses.push_back(parse_key(s));
    }
    std::vector<uint8_t> img = build_image(starts, hops, nodes);
    std::cout << to_hex(img) << '\n';
    for (U128 addr : addresses) print_answer(trace_image(img, addr));
    return 0;
}

int run_trace() {
    size_t a;
    std::string image;
    std::cin >> a >> image;
    if (!std::cin) throw std::runtime_error("truncated native input");
    std::vector<uint8_t> img = from_hex(image);
    std::vector<U128> addresses;
    for (size_t i = 0; i < a; ++i) {
        std::string s;
        std::cin >> s;
        if (!std::cin) throw std::runtime_error("truncated native input");
        addresses.push_back(parse_key(s));
    }
    for (U128 addr : addresses) print_answer(trace_image(img, addr));
    return 0;
}

struct CaseIn {
    int cache_pages, hit, miss, dec[3];
    std::vector<std::vector<Route>> versions;
    struct Burst { int version; long long rep; std::vector<U128> addrs; };
    std::vector<Burst> bursts;
};

int run_solve() {
    size_t ncases;
    std::cin >> ncases;
    if (!std::cin) throw std::runtime_error("truncated native input");
    std::vector<CaseIn> cases(ncases);
    for (CaseIn& cs : cases) {
        size_t nv;
        std::cin >> nv >> cs.cache_pages >> cs.hit >> cs.miss
                 >> cs.dec[0] >> cs.dec[1] >> cs.dec[2];
        if (!std::cin) throw std::runtime_error("truncated native input");
        cs.versions.resize(nv);
        for (auto& ver : cs.versions) {
            size_t n;
            std::cin >> n;
            ver.reserve(n);
            for (size_t i = 0; i < n; ++i) {
                std::string s;
                int length, hop;
                std::cin >> s >> length >> hop;
                if (!std::cin) throw std::runtime_error("truncated native input");
                ver.push_back({parse_key(s), length, hop});
            }
        }
        size_t nb;
        std::cin >> nb;
        cs.bursts.resize(nb);
        for (auto& bu : cs.bursts) {
            size_t na;
            std::cin >> bu.version >> bu.rep >> na;
            if (!std::cin) throw std::runtime_error("truncated native input");
            bu.addrs.resize(na);
            for (size_t i = 0; i < na; ++i) {
                std::string s;
                std::cin >> s;
                if (!std::cin) throw std::runtime_error("truncated native input");
                bu.addrs[i] = parse_key(s);
            }
        }
    }

    // Compile every committed version; enforce the forwarding-run domain.
    struct CaseRuns {
        std::vector<std::vector<Run>> versions;
        std::vector<std::vector<int>> addr_run;  // per burst, run index per address
    };
    std::vector<CaseRuns> compiled(ncases);
    long long total_runs = 0;
    for (size_t ci = 0; ci < ncases; ++ci) {
        CaseRuns& cr = compiled[ci];
        cr.versions.reserve(cases[ci].versions.size());
        for (const auto& ver : cases[ci].versions) {
            cr.versions.push_back(compile_runs(ver));
            total_runs += (long long)cr.versions.back().size();
        }
        for (const auto& bu : cases[ci].bursts) {
            const auto& runs = cr.versions[bu.version];
            std::vector<int> idx;
            idx.reserve(bu.addrs.size());
            for (U128 addr : bu.addrs) {
                // greatest run start <= addr (starts[0] == 0)
                auto it = std::upper_bound(runs.begin(), runs.end(), addr,
                    [](U128 v, const Run& r) { return v < r.start; });
                idx.push_back((int)(it - runs.begin()) - 1);
            }
            cr.addr_run.push_back(std::move(idx));
        }
    }
    for (const auto& cr : compiled)
        for (const auto& ver : cr.versions)
            if (ver.size() > 64) { std::cout << "INVALID\n"; return 0; }
    if (total_runs > 128) { std::cout << "INVALID\n"; return 0; }

    std::cout << "OK\n";
    for (size_t ci = 0; ci < ncases; ++ci) {
        const CaseIn& cs = cases[ci];
        const CaseRuns& cr = compiled[ci];
        size_t nv = cs.versions.size();
        int C = cs.cache_pages;

        // Per-version plans (work,pages) for every exact resident-page count.
        std::vector<VersionPlan> plans(nv);
        std::vector<std::vector<OptPair>> per(nv);
        for (size_t v = 0; v < nv; ++v) {
            std::vector<U128> starts;
            std::vector<BurstData> bd;
            for (const Run& r : cr.versions[v]) starts.push_back(r.start);
            int R = (int)starts.size();
            for (const CaseIn::Burst& bu : cs.bursts) {
                if (bu.version != (int)v) continue;
                BurstData d;
                d.rep = bu.rep;
                d.cnt.assign(R, 0);
                for (int ri : cr.addr_run[&bu - &cs.bursts[0]]) d.cnt[ri]++;
                bd.push_back(std::move(d));
            }
            plans[v].run(starts, bd, C, cs.hit, cs.miss, cs.dec);
            per[v] = plans[v].best;
        }

        // Joint resident-budget combination across versions of this case.
        std::vector<OptPair> cur(C + 1, {INFLL, 0});
        std::vector<int> back(nv * (C + 1), -1);
        cur[0] = {0, 0};
        for (size_t v = 0; v < nv; ++v) {
            std::vector<OptPair> nxt(C + 1, {INFLL, 0});
            for (int q = 0; q <= C; ++q) {
                for (int p = 0; p <= q; ++p) {
                    if (cur[p].w >= INFLL || per[v][q - p].w >= INFLL) continue;
                    long long w = cur[p].w + per[v][q - p].w;
                    int pg = cur[p].p + per[v][q - p].p;
                    if (w < nxt[q].w || (w == nxt[q].w && pg < nxt[q].p)) {
                        nxt[q] = {w, pg};
                        back[v * (C + 1) + q] = p;
                    }
                }
            }
            cur = nxt;
        }
        int bestq = 0;
        for (int q = 0; q <= C; ++q)
            if (pair_less(cur[q].w, cur[q].p, cur[bestq].w, cur[bestq].p)) bestq = q;
        OptPair optimum = cur[bestq];
        std::vector<int> use(nv, 0);
        {
            int q = bestq;
            for (size_t v = nv; v-- > 0;) {
                use[v] = q - back[v * (C + 1) + q] ... ;
            }
        }
        (void)optimum; (void)use;
    }
    return 0;
}

}  // namespace

int main() {
    try {
        std::string command;
        if (!(std::cin >> command)) throw std::runtime_error("native command");
        if (command == "ATLAS") return run_atlas();
        if (command == "PACK") return run_pack();
        if (command == "TRACE") return run_trace();
        if (command == "SOLVE") return run_solve();
        throw std::runtime_error("unknown native command");
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
